nodes.command:
cat << 'EOF' > "workflows/project/logs/reports/${nodes.intake.output.acceptance_id}-progress.md"
# 进度报告 - ${inputs.milestone_id}
> 生成时间: $(date '+%Y-%m-%d %H:%M:%S')

## 总体进度
- 任务总数: ${nodes.generate_summary.output.tasks_total}
- 代码审查通过率: ${nodes.generate_summary.output.code_review_pass_rate}
- 设计审查通过率: ${nodes.generate_summary.output.design_review_pass_rate}
- QA签字通过率: ${nodes.generate_summary.output.qa_pass_rate}
- 综合通过率: ${nodes.generate_summary.output.overall_pass_rate}
- 平均代码审查分数: ${nodes.generate_summary.output.avg_code_review_score}

## 决策建议
- **决策**: ${nodes.determine_decision.output.decision}
- **原因**: ${nodes.determine_decision.output.reason}

## 下一步
$(echo '${JSON.stringify(nodes.generate_progress_report.output.next_steps)}' | sed 's/\[//' | sed 's/\]//' | sed 's/","/\n- /g' | sed 's/"//g' | sed 's/^/- /')
EOF
mkdir -p workflows/project/logs/reports
